-- ============================================================================
-- The Indian Itinerary Project — Schema (PostgreSQL-flavoured)
-- ============================================================================
-- A SQLite-compatible copy of this data is generated by
-- scripts/08_generate_database.py -> final_dataset/indian_itinerary.db
-- (SQLite lacks UUID/gen_random_uuid(), so that build path loads data
-- directly from the cleaned DataFrames using TEXT primary keys instead.)
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS "pgcrypto"; -- for gen_random_uuid()

-- ---------------------------------------------------------------------------
-- Domain 1: Real attractions + climate data
-- ---------------------------------------------------------------------------

CREATE TABLE states (
    state_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    state_name  TEXT NOT NULL UNIQUE,
    zone        TEXT
);

CREATE TABLE cities (
    city_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    city_name   TEXT NOT NULL,
    state_id    UUID NOT NULL REFERENCES states(state_id),
    UNIQUE (city_name, state_id)
);

CREATE TABLE weather (
    weather_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    city_id         UUID NOT NULL UNIQUE REFERENCES cities(city_id),
    jan_max_temp    SMALLINT, jan_min_temp SMALLINT,
    feb_max_temp    SMALLINT, feb_min_temp SMALLINT,
    mar_max_temp    SMALLINT, mar_min_temp SMALLINT,
    apr_max_temp    SMALLINT, apr_min_temp SMALLINT,
    may_max_temp    SMALLINT, may_min_temp SMALLINT,
    jun_max_temp    SMALLINT, jun_min_temp SMALLINT,
    jul_max_temp    SMALLINT, jul_min_temp SMALLINT,
    aug_max_temp    SMALLINT, aug_min_temp SMALLINT,
    sep_max_temp    SMALLINT, sep_min_temp SMALLINT,
    oct_max_temp    SMALLINT, oct_min_temp SMALLINT,
    nov_max_temp    SMALLINT, nov_min_temp SMALLINT,
    dec_max_temp    SMALLINT, dec_min_temp SMALLINT,
    avg_max_temp_c      NUMERIC(5,2),
    avg_min_temp_c      NUMERIC(5,2),
    summer_suitability  TEXT CHECK (summer_suitability IN ('High','Medium','Low')),
    winter_suitability  TEXT CHECK (winter_suitability IN ('High','Medium','Low')),
    monsoon_suitability TEXT CHECK (monsoon_suitability IN ('High','Medium','Low'))
);

CREATE TABLE climate_monthly (
    climate_monthly_id INTEGER PRIMARY KEY,
    city_id                UUID NOT NULL REFERENCES cities(city_id),
    month_number           SMALLINT NOT NULL CHECK (month_number BETWEEN 1 AND 12),
    month_name             TEXT NOT NULL,
    avg_high_temp_c        NUMERIC(5,2),
    avg_low_temp_c         NUMERIC(5,2),
    avg_rainfall_mm        NUMERIC(7,2),
    relative_humidity_pct  NUMERIC(5,2),
    rainy_days             NUMERIC(4,1),
    uv_index               NUMERIC(4,1),
    weather_category       TEXT CHECK (weather_category IN ('Pleasant','Hot','Very Hot','Cold','Rainy')),
    comfort_score          NUMERIC(5,2),
    source_primary         TEXT,
    data_quality_note      TEXT,
    matched_place          TEXT,
    geocode_method         TEXT,
    UNIQUE (city_id, month_number)
);

CREATE TABLE attractions (
    attraction_id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    city_id                     UUID REFERENCES cities(city_id),
    attraction_name             TEXT NOT NULL,
    attraction_type             TEXT,
    significance                TEXT,
    establishment_year          SMALLINT,
    visit_duration_hrs          NUMERIC(4,1),
    google_rating               NUMERIC(2,1) CHECK (google_rating BETWEEN 0 AND 5),
    entrance_fee_inr            INTEGER CHECK (entrance_fee_inr >= 0),
    airport_within_50km         BOOLEAN,
    weekly_off_day              TEXT,
    dslr_allowed                BOOLEAN,
    google_review_count_lakhs   NUMERIC(6,2),
    best_time_of_day            TEXT,
    zone                        TEXT,
    -- engineered features
    budget_category             TEXT CHECK (budget_category IN ('Free','Low','Medium','High','Unknown')),
    adventure_score              SMALLINT, photography_score SMALLINT, culture_score SMALLINT,
    history_score                SMALLINT, nature_score SMALLINT, pilgrimage_score SMALLINT,
    unesco_indicator BOOLEAN, mountain_indicator BOOLEAN, beach_indicator BOOLEAN,
    wildlife_indicator BOOLEAN, religious_indicator BOOLEAN, heritage_indicator BOOLEAN,
    adventure_indicator BOOLEAN,
    dslr_friendly BOOLEAN, weekend_friendly BOOLEAN, road_trip_friendly BOOLEAN,
    popularity_tier TEXT CHECK (popularity_tier IN ('Niche','Emerging','Popular','Iconic')),
    recommended_trip_length_hrs NUMERIC(4,1),
    estimated_daily_cost_inr    INTEGER,
    family_score SMALLINT, solo_score SMALLINT, couple_score SMALLINT,
    senior_friendly BOOLEAN, backpacker_friendly BOOLEAN, digital_nomad_friendly BOOLEAN,
    accessibility_score SMALLINT,
    travel_complexity TEXT CHECK (travel_complexity IN ('Low','Medium','High')),
    suggested_season_note TEXT
);

CREATE TABLE destination_climate (
    attraction_id               UUID PRIMARY KEY REFERENCES attractions(attraction_id),
    attraction_name             TEXT NOT NULL,
    city_id                     UUID REFERENCES cities(city_id),
    best_months_to_visit        TEXT,
    warmest_month               TEXT,
    coldest_month               TEXT,
    wettest_month               TEXT,
    average_annual_temp_c       NUMERIC(5,2),
    average_annual_rainfall_mm  NUMERIC(8,2),
    average_humidity_pct        NUMERIC(5,2),
    source_summary              TEXT
);

CREATE TABLE tags (
    tag_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tag_name  TEXT NOT NULL UNIQUE
);

CREATE TABLE destination_tags (
    attraction_id UUID NOT NULL REFERENCES attractions(attraction_id),
    tag_id        UUID NOT NULL REFERENCES tags(tag_id),
    PRIMARY KEY (attraction_id, tag_id)
);

-- ---------------------------------------------------------------------------
-- Domain 2: Synthetic user-engagement data (see docs/DATASET_UNDERSTANDING.md
-- for why this is NOT foreign-keyed to `attractions` above)
-- ---------------------------------------------------------------------------

CREATE TABLE sim_destinations (
    sim_destination_id  INTEGER PRIMARY KEY,
    destination_name    TEXT NOT NULL,
    destination_type    TEXT,
    popularity_score     NUMERIC(5,2) CHECK (popularity_score BETWEEN 0 AND 10),
    best_time_to_visit  TEXT,
    state_id             UUID REFERENCES states(state_id)
);

CREATE TABLE sim_users (
    sim_user_id      INTEGER PRIMARY KEY,
    user_name        TEXT,
    email            TEXT,
    preferences_raw  TEXT,
    gender           TEXT,
    num_adults       SMALLINT CHECK (num_adults >= 0),
    num_children     SMALLINT CHECK (num_children >= 0)
);

CREATE TABLE sim_reviews (
    sim_review_id       INTEGER PRIMARY KEY,
    sim_destination_id  INTEGER NOT NULL REFERENCES sim_destinations(sim_destination_id),
    sim_user_id         INTEGER NOT NULL REFERENCES sim_users(sim_user_id),
    rating               SMALLINT CHECK (rating BETWEEN 1 AND 5),
    review_text          TEXT
);

CREATE TABLE sim_user_history (
    sim_history_id       INTEGER PRIMARY KEY,
    sim_user_id          INTEGER NOT NULL REFERENCES sim_users(sim_user_id),
    sim_destination_id   INTEGER NOT NULL REFERENCES sim_destinations(sim_destination_id),
    visit_date            DATE,
    experience_rating     SMALLINT CHECK (experience_rating BETWEEN 1 AND 5)
);

-- Data provenance / lineage table (governance best practice)
CREATE TABLE data_sources (
    source_id     UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    source_name   TEXT NOT NULL,
    original_file TEXT NOT NULL,
    domain        TEXT NOT NULL CHECK (domain IN ('real', 'synthetic')),
    description   TEXT,
    loaded_at     TIMESTAMPTZ DEFAULT now()
);
